@php
$permisosActuales=old('permisos',$usuario->permisos ?? \App\Support\Permisos::perfil($usuario->encargado_id?'cajero':'encargado'));$esPersonal=$esPersonal??false;
$grupos=collect(\App\Support\Permisos::LISTA)->groupBy(fn($label,$key)=>explode('.',$key)[0],preserveKeys:true);
@endphp
<fieldset class="permission-box" data-permisos-selector><legend>Acceso por módulo y acción</legend><input type="hidden" name="permisos_enviados" value="1"><p>Los módulos contratados por el negocio limitan estos permisos. Los permisos de lectura necesarios se agregan al guardar.</p><div class="permission-presets">@foreach(['cajero'=>'Cajero POS','contador'=>'Contador','operador'=>'Documentos','encargado'=>'Todos los disponibles','ninguno'=>'Ninguno'] as $key=>$label)<button class="btn btn-sec" type="button" data-perfil="{{ $key }}">{{ $label }}</button>@endforeach</div>
@foreach($grupos as $grupo=>$permisos)<details open class="permission-group"><summary>{{ \App\Support\Negocios::MODULOS[$grupo] ?? ucfirst($grupo) }}</summary><div class="form-grid">@foreach($permisos as $clave=>$etiqueta)@if($clave==='clientes.eliminar')@continue @endif @if(!$esPersonal || (!in_array($clave,['personal','clientes.acceso','clientes.permisos','clientes.eliminar'],true) && (auth()->user()->esAdmin() || auth()->user()->tienePermiso($clave))))<label><input type="checkbox" name="permisos[]" value="{{ $clave }}" @checked(in_array($clave,$permisosActuales,true))>{{ $etiqueta }}</label>@endif @endforeach</div></details>@endforeach
<p class="mt-3 text-xs text-gray-500">La eliminación de clientes está reservada al administrador general. El acceso y los permisos de edición del portal se administran desde una cuenta encargada.</p><script type="application/json" data-presets>{!! json_encode(['cajero'=>\App\Support\Permisos::perfil('cajero'),'contador'=>\App\Support\Permisos::perfil('contador'),'operador'=>\App\Support\Permisos::perfil('operador'),'encargado'=>\App\Support\Permisos::perfil('encargado'),'ninguno'=>[]],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) !!}</script></fieldset>
@once @push('scripts')<script>document.querySelectorAll('[data-permisos-selector]').forEach(box=>{const presets=JSON.parse(box.querySelector('[data-presets]').textContent);box.querySelectorAll('[data-perfil]').forEach(b=>b.addEventListener('click',()=>box.querySelectorAll('input[type=checkbox]').forEach(i=>i.checked=presets[b.dataset.perfil].includes(i.value))));});</script>@endpush @endonce